(4096867, 587932, 62095, '<td valign="top">A difficult shot to recreate exactly, good effort.</td>', 'A difficult shot to recreate exactly, good effort.', '2007-09-17 16:11:49.000000', NULL, 1),
(4096871, 587806, 62095, '<td valign="top">A faithful recreation, better in some respects, but lacking in the dramatic lighting of the original.</td>', 'A faithful recreation, better in some respects, but lacking in the dramatic lighting of the original.', '2007-09-17 16:13:22.000000', NULL, 1),
(4096874, 587566, 62095, '<td valign="top">I think that some of the qualities of the original, such as the background and the softness throughout are not as evident here, though your photo on its own merits is impressive.</td>', 'I think that some of the qualities of the original, such as the background and the softness throughout are not as evident here, though your photo on its own merits is impressive.', '2007-09-17 16:15:39.000000', NULL, 1),
(4096876, 587917, 59577, '<td valign="top">I''m amazed you could get the same effect with just Advanced. The other guy had to use Expert!!!<br/>Too funny. Thank you :)</td>', 'I''m amazed you could get the same effect with just Advanced. The other guy had to use Expert!!!Too funny. Thank you :)', '2007-09-17 16:16:34.000000', NULL, 1),
(4096879, 588042, 62095, '<td valign="top">Almost there, the original had a touch more clarity to it I think.</td>', 'Almost there, the original had a touch more clarity to it I think.', '2007-09-17 16:17:13.000000', NULL, 1),
(4096882, 587886, 62095, '<td valign="top">not an easy shot to recreate. You''ve taken a more top-down angle for your shot which makes for a different overall feel.</td>', 'not an easy shot to recreate. You''ve taken a more top-down angle for your shot which makes for a different overall feel.', '2007-09-17 16:19:15.000000', NULL, 1),
(4096894, 587377, 62095, '<td valign="top">A good shot. The original was a clever use of colour, which your shot imitates, though the green in the original appears slightly more seemless.</td>', 'A good shot. The original was a clever use of colour, which your shot imitates, though the green in the original appears slightly more seemless.', '2007-09-17 16:21:06.000000', NULL, 1),
(4096901, 587964, 62095, '<td valign="top">I actually prefer your apple to the original, but I prefer the original''s paper leaves.</td>', 'I actually prefer your apple to the original, but I prefer the original''s paper leaves.', '2007-09-17 16:22:16.000000', NULL, 1),
(4096902, 587294, 59577, '<td valign="top">I prefer this one. It''s a shame some of the corks blend into the background. Good luck.</td>', 'I prefer this one. It''s a shame some of the corks blend into the background. Good luck.', '2007-09-17 16:22:21.000000', NULL, 1),
(4096909, 587819, 62095, '<td valign="top">Very good recreation.</td>', 'Very good recreation.', '2007-09-17 16:23:46.000000', NULL, 1),
(4096913, 587397, 62095, '<td valign="top">An even more surreal version of the original.</td>', 'An even more surreal version of the original.', '2007-09-17 16:24:59.000000', NULL, 1),
(4096918, 587491, 62095, '<td valign="top">very good. I like all the patterns going on here. I prefer your choice of colours.</td>', 'very good. I like all the patterns going on here. I prefer your choice of colours.', '2007-09-17 16:26:41.000000', NULL, 1),
(4096924, 585689, 62095, '<td valign="top">The original had, of course, only basic editing to work with, but your globe is very impressive.</td>', 'The original had, of course, only basic editing to work with, but your globe is very impressive.', '2007-09-17 16:29:31.000000', NULL, 1),
(4096945, 587964, 19944, '<td valign="top">I wish your pages were cut a little more smoothly and and oriented horizontally.</td>', 'I wish your pages were cut a little more smoothly and and oriented horizontally.', '2007-09-17 16:37:46.000000', NULL, 1),
(4096948, 587648, 19944, '<td valign="top">The best of the iBook take-offs.  Smooth cut. Sharp photo.<br/> <br/>I dare say...better than the original.</td>', 'The best of the iBook take-offs.  Smooth cut. Sharp photo. I dare say...better than the original.', '2007-09-17 16:38:52.000000', NULL, 1),
(4096963, 587934, 19944, '<td valign="top">This is about as close to the original as any in the challenge.  The tones are dead-on.  congratulations.</td>', 'This is about as close to the original as any in the challenge.  The tones are dead-on.  congratulations.', '2007-09-17 16:43:28.000000', NULL, 1),
(4097105, 587871, 19944, '<td valign="top">Although Christopher''s lighting is more dramatic, I like the way your background fades to darkness sooner.  Excellent job.</td>', 'Although Christopher''s lighting is more dramatic, I like the way your background fades to darkness sooner.  Excellent job.', '2007-09-17 17:39:39.000000', NULL, 1),
(4097109, 586466, 19944, '<td valign="top">An admirable effort, but I still have to go with Shannon''s original.  The cut of the egg is much smoother and the entire shot is just overall sharper.</td>', 'An admirable effort, but I still have to go with Shannon''s original.  The cut of the egg is much smoother and the entire shot is just overall sharper.', '2007-09-17 17:42:00.000000', NULL, 1),
(4097113, 587381, 19944, '<td valign="top">Great rendition.  One of the best of the challenge.  You nailed the exposure almost perfectly.</td>', 'Great rendition.  One of the best of the challenge.  You nailed the exposure almost perfectly.', '2007-09-17 17:43:13.000000', NULL, 1),
(4097119, 587917, 70, '<td valign="top">Is this an ode to Silverfoxx or Leroy?</td>', 'Is this an ode to Silverfoxx or Leroy?', '2007-09-17 17:46:06.000000', NULL, 1),
(4097132, 587927, 55838, '<td valign="top">Back to comment - Did you have as much fun as I did doing this?  : )  I hope so!  Excellent job on the makeup!  Adding to favorites of course!</td>', 'Back to comment - Did you have as much fun as I did doing this?  : )  I hope so!  Excellent job on the makeup!  Adding to favorites of course!', '2007-09-17 17:50:54.000000', NULL, 1),
(4097142, 587830, 55838, '<td valign="top">So did you use exactly 552 pins too?  : )  This is very cool and an extra point for the rhyme!  Adding to favorites of course!</td>', 'So did you use exactly 552 pins too?  : )  This is very cool and an extra point for the rhyme!  Adding to favorites of course!', '2007-09-17 17:54:17.000000', NULL, 1),
(4097152, 585335, 64929, '<td valign="top">Definitely my favorite of the challenge entries!  The motion, the texture of the eggs...just darn cool!  *10*</td>', 'Definitely my favorite of the challenge entries!  The motion, the texture of the eggs...just darn cool!  *10*', '2007-09-17 17:58:26.000000', NULL, 1),
(4097154, 587381, 64929, '<td valign="top">So soft and refreshing...well done!  Like a porcelain doll....*9*</td>', 'So soft and refreshing...well done!  Like a porcelain doll....*9*', '2007-09-17 17:58:56.000000', NULL, 1),
(4097156, 586235, 64929, '<td valign="top">Just an incredible capture in every way!  Dare I say it...better than the original! *10*</td>', 'Just an incredible capture in every way!  Dare I say it...better than the original! *10*', '2007-09-17 17:59:38.000000', NULL, 1),
(4097157, 588036, 64929, '<td valign="top">Excellent re-capture of a brilliant shot!  Bravo to you!  *9*</td>', 'Excellent re-capture of a brilliant shot!  Bravo to you!  *9*', '2007-09-17 18:00:04.000000', NULL, 1),
(4097159, 587254, 64929, '<td valign="top">Well done re-capture of a brilliant photo!  Bravo to you!!!!...and get some shampoo and soap for that lovely model!  LOL  *8*</td>', 'Well done re-capture of a brilliant photo!  Bravo to you!!!!...and get some shampoo and soap for that lovely model!  LOL  *8*', '2007-09-17 18:01:10.000000', NULL, 1),
(4097161, 588038, 39110, '<td valign="top">The red background does not suit the innocent feel of the photo</td>', 'The red background does not suit the innocent feel of the photo', '2007-09-17 18:01:29.000000', NULL, 1),
(4097163, 585034, 64929, '<td valign="top">Excellent re-capture of this wonderful set-up...Bravo to you!!  The green just ''pops'' and the detail/clarity is spot on! *9*</td>', 'Excellent re-capture of this wonderful set-up...Bravo to you!!  The green just ''pops'' and the detail/clarity is spot on! *9*', '2007-09-17 18:02:15.000000', NULL, 1),
(4097164, 587941, 64929, '<td valign="top">Great pyschodelic feel...the colors just ''pop!''  Bravo to you!! *7*</td>', 'Great pyschodelic feel...the colors just ''pop!''  Bravo to you!! *7*', '2007-09-17 18:02:51.000000', NULL, 1),
(4097168, 587886, 64929, '<td valign="top">Irene''s work with droplets is a tough nut to crack...you did an admirable job!  Bravo!  It''s all about the timing.  The inside even looks like a SMILE! The ends of the ''splatter'' could be a bit sharper and more defined but worthy attempt! *8*</td>', 'Irene''s work with droplets is a tough nut to crack...you did an admirable job!  Bravo!  It''s all about the timing.  The inside even looks like a SMILE! The ends of the ''splatter'' could be a bit sharper and more defined but worthy attempt! *8*', '2007-09-17 18:04:41.000000', NULL, 1),
(4097170, 588042, 64929, '<td valign="top">Really nice job!!  My only criticism is that it needs a bit straightening, as the glass looks like it leans to the left, IMHO. *7*</td>', 'Really nice job!!  My only criticism is that it needs a bit straightening, as the glass looks like it leans to the left, IMHO. *7*', '2007-09-17 18:05:57.000000', NULL, 1),
(4097171, 587799, 64929, '<td valign="top">Great psycholdelic feel to this one!  Brilliant colors, very nice! *7*</td>', 'Great psycholdelic feel to this one!  Brilliant colors, very nice! *7*', '2007-09-17 18:06:53.000000', NULL, 1),
(4097174, 587648, 64929, '<td valign="top">Excellent re-capture of this brilliant set-up!  While a couple of others in the challenge tried to duplicate the original, yours is spot on!  Bravo!</td>', 'Excellent re-capture of this brilliant set-up!  While a couple of others in the challenge tried to duplicate the original, yours is spot on!  Bravo!', '2007-09-17 18:07:48.000000', NULL, 1),
(4097177, 587917, 64929, '<td valign="top">Oh My!  You must have been looking to capture "the most commented-on image" with this one! Daring and creative...gotta give bonus points for that! *8*</td>', 'Oh My!  You must have been looking to capture "the most commented-on image" with this one! Daring and creative...gotta give bonus points for that! *8*', '2007-09-17 18:08:48.000000', NULL, 1),
(4097178, 587254, 39110, '<td valign="top">The processing and technicals is very good and if I remmeber correctly very similar to Larus''s photo but i feel there is a bit too much dirt.</td>', 'The processing and technicals is very good and if I remmeber correctly very similar to Larus''s photo but i feel there is a bit too much dirt.', '2007-09-17 18:08:55.000000', NULL, 1),
(4097180, 587284, 64929, '<td valign="top">Great color and clarity!  Really impressive work! *8*</td>', 'Great color and clarity!  Really impressive work! *8*', '2007-09-17 18:09:18.000000', NULL, 1),
(4097184, 588000, 64929, '<td valign="top">Dang!  This looks JUST LIKE the cat done by Yanko!  Uncanny!  Bravo to you for an excellent re-capture! *8*</td>', 'Dang!  This looks JUST LIKE the cat done by Yanko!  Uncanny!  Bravo to you for an excellent re-capture! *8*', '2007-09-17 18:10:37.000000', NULL, 1),
