INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4098614, 587161, 3569, '<td valign="top">wonderful desert scene revised.</td>', 'wonderful desert scene revised.', '2007-09-18 10:33:59.000000', NULL, 1),
(4098620, 585034, 3569, '<td valign="top">In the ribbons for sure.  Great shot.</td>', 'In the ribbons for sure.  Great shot.', '2007-09-18 10:36:42.000000', NULL, 1),
(4098681, 587828, 55956, '<td valign="top">very good portrait.</td>', 'very good portrait.', '2007-09-18 11:18:47.000000', NULL, 1),
(4098923, 587917, 82707, '<td valign="top">LOL!!!!  I think I''m scarred for life!  At least you can''t be accused of violating copyright on the original...not even close.  I''ve probably scored it higher than it deserves because you so obviously need all the help you can get, and I really did enjoy your sense of the ridiculous!</td>', 'LOL!!!!  I think I''m scarred for life!  At least you can''t be accused of violating copyright on the original...not even close.  I''ve probably scored it higher than it deserves because you so obviously need all the help you can get, and I really did enjoy your sense of the ridiculous!', '2007-09-18 13:05:09.000000', NULL, 1),
(4098942, 585662, 43463, '<td valign="top">I did take a look at the original because your entry arose my curiosity. It is all about the angle of shooting which is how I *think* this illusion is achieved. Anyway, love how the white of your main subject realllllly pops off the deep black backdrop. Your composition just pops visually and the illusion you present to us in the composition holds the viewer''s attention as we scratch our heads and think "now how did he/she do that?!":-) Lighting and level of details are great in this one. Love how you added a slightly different touch with the pencil being the the same blue tone of the push pin. Visually the color is appealing not to mention it too pops off the white backdrop it rests on.</td>', 'I did take a look at the original because your entry arose my curiosity. It is all about the angle of shooting which is how I *think* this illusion is achieved. Anyway, love how the white of your main subject realllllly pops off the deep black backdrop. Your composition just pops visually and the illusion you present to us in the composition holds the viewer''s attention as we scratch our heads and think "now how did he/she do that?!":-) Lighting and level of details are great in this one. Love how you added a slightly different touch with the pencil being the the same blue tone of the push pin. Visually the color is appealing not to mention it too pops off the white backdrop it rests on.', '2007-09-18 13:24:27.000000', NULL, 1),
(4098949, 587828, 43463, '<td valign="top">Absolutely wow! The B&amp;W tones in this photo composition are simply stellar! You have a great dynamic range in your shadows and hightlights. Love the square crop for it really keeps the viewers attention tightly focused on your main subject. Love the look on the little girl''s face it has much emotion - one just wonders what is so astonishing in what she sees. A very nice emulation of the original.</td>', 'Absolutely wow! The B&W tones in this photo composition are simply stellar! You have a great dynamic range in your shadows and hightlights. Love the square crop for it really keeps the viewers attention tightly focused on your main subject. Love the look on the little girl''s face it has much emotion - one just wonders what is so astonishing in what she sees. A very nice emulation of the original.', '2007-09-18 13:29:16.000000', NULL, 1),
(4098954, 585034, 43463, '<td valign="top">The level of detail on the leaf and the rich green and yellow tones is simply stunning!!! Love the shadow of the frog that we see from the underside of this leaf. You did a stunningly bang up job on reproducing the original. Really excellent work and I have absolutely nothing to suggest on how to improve this one:-)</td>', 'The level of detail on the leaf and the rich green and yellow tones is simply stunning!!! Love the shadow of the frog that we see from the underside of this leaf. You did a stunningly bang up job on reproducing the original. Really excellent work and I have absolutely nothing to suggest on how to improve this one:-)', '2007-09-18 13:34:33.000000', NULL, 1),
(4098962, 588040, 60614, '<td valign="top">This is an awesome tribute.  Well done.  He looks so cute with pink eyelashes.</td>', 'This is an awesome tribute.  Well done.  He looks so cute with pink eyelashes.', '2007-09-18 13:39:21.000000', NULL, 1),
(4098967, 587789, 43463, '<td valign="top">Love the colors and the leading lines that draw the eye to travel the path to the lighthouse off into the horizon. A very beautiful and idyllic scenery. Love how you captured some ''action'' going on in the composition as well - the waves off on the right hand side contrast greatly with the more calmer seas on the left. Mad_Brewers composition is more of a lighter &amp; airy early daytime shot whereas your''s is a nice companion piece that shows us the sunset &amp; a much more moodier edge/feel. Great job.</td>', 'Love the colors and the leading lines that draw the eye to travel the path to the lighthouse off into the horizon. A very beautiful and idyllic scenery. Love how you captured some ''action'' going on in the composition as well - the waves off on the right hand side contrast greatly with the more calmer seas on the left. Mad_Brewers composition is more of a lighter & airy early daytime shot whereas your''s is a nice companion piece that shows us the sunset & a much more moodier edge/feel. Great job.', '2007-09-18 13:41:25.000000', NULL, 1),
(4098978, 585629, 43463, '<td valign="top">I''ve seen this done many times before but it is STILL a wonderful optical illusion that really draws the eye in. You did an excellent job in capturing the refracted flag in each and every waterdrop. I like how this composition also has varying sizes in each waterdrop for it creates visual interest &amp; increases the visual appeal of the overall composition. Color and lighting is great in your capture. Well done.</td>', 'I''ve seen this done many times before but it is STILL a wonderful optical illusion that really draws the eye in. You did an excellent job in capturing the refracted flag in each and every waterdrop. I like how this composition also has varying sizes in each waterdrop for it creates visual interest & increases the visual appeal of the overall composition. Color and lighting is great in your capture. Well done.', '2007-09-18 13:45:18.000000', NULL, 1),
(4098982, 587799, 56999, '<td valign="top">Nicely done, a beautiful image.</td>', 'Nicely done, a beautiful image.', '2007-09-18 13:47:47.000000', NULL, 1),
(4098985, 587901, 56999, '<td valign="top">Great job.</td>', 'Great job.', '2007-09-18 13:49:36.000000', NULL, 1),
(4098989, 587832, 56999, '<td valign="top">Wonderful image, you captured her beauty through the muck.</td>', 'Wonderful image, you captured her beauty through the muck.', '2007-09-18 13:52:00.000000', NULL, 1),
(4098990, 587664, 56999, '<td valign="top">Love the colors and the execution.</td>', 'Love the colors and the execution.', '2007-09-18 13:52:48.000000', NULL, 1),
(4098997, 587917, 56999, '<td valign="top">What a crack up, great four pack.</td>', 'What a crack up, great four pack.', '2007-09-18 13:55:02.000000', NULL, 1),
(4099002, 586207, 56999, '<td valign="top">Wonderful capture.</td>', 'Wonderful capture.', '2007-09-18 13:56:07.000000', NULL, 1),
(4099010, 586207, 49109, '<td valign="top">needs a boost in saturation, otherise very well done</td>', 'needs a boost in saturation, otherise very well done', '2007-09-18 13:58:34.000000', NULL, 1),
(4099011, 587238, 43463, '<td valign="top">A Magical Place is one of my favorites. I think you did an excellent job in trying to emulate the original. While the pink color of the daisy does not show the ring of light that illuminates the yellow/orange daisy of the original you do have a burst of lovely yellow hues from the center portion of the flower. Love the rich warm tones and the level of detail you show us in that center yellow portion of the flower. I also love the sharp yet soft feel of the pink petals of the flower. I''m not sure but the thin pink border does not seem to exactly match any of the hues in the flower petals. I think that pink border would be better if you picked a deeper pink from one of the flower petals (mayhap you did but I think a deeper tone than the paler one here would work better) One last critique, there is something in the background off to the left side of the flower. Either it is movement or an object but nonetheless it becomes an added element that detracts attention away from your main focus. Eliminating that will really help make your flower pop off more on that black backdrop.</td>', 'A Magical Place is one of my favorites. I think you did an excellent job in trying to emulate the original. While the pink color of the daisy does not show the ring of light that illuminates the yellow/orange daisy of the original you do have a burst of lovely yellow hues from the center portion of the flower. Love the rich warm tones and the level of detail you show us in that center yellow portion of the flower. I also love the sharp yet soft feel of the pink petals of the flower. I''m not sure but the thin pink border does not seem to exactly match any of the hues in the flower petals. I think that pink border would be better if you picked a deeper pink from one of the flower petals (mayhap you did but I think a deeper tone than the paler one here would work better) One last critique, there is something in the background off to the left side of the flower. Either it is movement or an object but nonetheless it becomes an added element that detracts attention away from your main focus. Eliminating that will really help make your flower pop off more on that black backdrop.', '2007-09-18 13:58:51.000000', NULL, 1),
(4099026, 584989, 56999, '<td valign="top">Beautiful image and model. Love the skin tone against the material.</td>', 'Beautiful image and model. Love the skin tone against the material.', '2007-09-18 14:05:32.000000', NULL, 1),
