(4099729, 587832, 27482, '<td valign="top">Hehe, honored you chose one of mine to tribute :)  Dig the noise and the white sand/dirt instead of the black I used.</td>', 'Hehe, honored you chose one of mine to tribute :)  Dig the noise and the white sand/dirt instead of the black I used.', '2007-09-18 20:49:40.000000', NULL, 1),
(4099734, 587954, 27482, '<td valign="top">Honored you chose one of mine to tribute to :)  Nice shot, mine actually wasn´t a silhouette but unless you have a pretty powerful light I guess there was nothing you could have done with it, hope people are not slamming it because of that cause I actually like this shot as a silhouette.  Nice sky and I dig the poles in the shot, it was an important element in my shot as well.</td>', 'Honored you chose one of mine to tribute to :)  Nice shot, mine actually wasn´t a silhouette but unless you have a pretty powerful light I guess there was nothing you could have done with it, hope people are not slamming it because of that cause I actually like this shot as a silhouette.  Nice sky and I dig the poles in the shot, it was an important element in my shot as well.', '2007-09-18 20:51:18.000000', NULL, 1),
(4099744, 587254, 27482, '<td valign="top">Honored you chose one of mine to pay tribute to :)  This one is very well done if the goal was to "copy" mine, it´s got the same look and it´s processed exactly as I would have processed mine.  She´s got a diffrent expression than Henny did and I like that about it and the eyes definately grab one´s attention.</td>', 'Honored you chose one of mine to pay tribute to :)  This one is very well done if the goal was to "copy" mine, it´s got the same look and it´s processed exactly as I would have processed mine.  She´s got a diffrent expression than Henny did and I like that about it and the eyes definately grab one´s attention.', '2007-09-18 20:52:59.000000', NULL, 1),
(4099750, 585363, 27482, '<td valign="top">Honored you chose one of mine to pay tribue to :)  I like that the lighting is more soft in this shot, makes it more a timeless photo than mine, a bit more artsy as well.  Also cool you decided to duotone it, I was not sure when I chose to have mine in "color" (although it may as well have been sepia toned as all the colors in it was so similar).  Nice job!</td>', 'Honored you chose one of mine to pay tribue to :)  I like that the lighting is more soft in this shot, makes it more a timeless photo than mine, a bit more artsy as well.  Also cool you decided to duotone it, I was not sure when I chose to have mine in "color" (although it may as well have been sepia toned as all the colors in it was so similar).  Nice job!', '2007-09-18 20:55:11.000000', NULL, 1),
(4099820, 587566, 19944, '<td valign="top">A great shot of the eagle.  Not as soft as the Doc''s, but very regal.  I might have cloned out that thread (or feather string...whatever) above his beak.</td>', 'A great shot of the eagle.  Not as soft as the Doc''s, but very regal.  I might have cloned out that thread (or feather string...whatever) above his beak.', '2007-09-18 21:21:34.000000', NULL, 1),
