(4101074, 587774, 69684, '<td valign="top">Although I prefer the orginal, this is also a very nice shot.</td>', 'Although I prefer the orginal, this is also a very nice shot.', '2007-09-19 07:51:40.000000', NULL, 1),
(4101412, 587328, 43463, '<td valign="top">Love the splashes of bold yellows on the blue background. It really pops visually off the page. I also like the change of using a different flower in which the center portion of the flower extrudes out - just another little visual element for the eye to appreciate and it makes the flowers stand out more. I do like the bokeh effect on where the flowers in the background are blurred but I do wonder if it would have more visual "pop" if you increased the DOF such that the foreground &amp; background are in sharper detail. Square crop keeps our attention nice and focused on the main subjects. Color and lighting is spot on. Great job here!</td>', 'Love the splashes of bold yellows on the blue background. It really pops visually off the page. I also like the change of using a different flower in which the center portion of the flower extrudes out - just another little visual element for the eye to appreciate and it makes the flowers stand out more. I do like the bokeh effect on where the flowers in the background are blurred but I do wonder if it would have more visual "pop" if you increased the DOF such that the foreground & background are in sharper detail. Square crop keeps our attention nice and focused on the main subjects. Color and lighting is spot on. Great job here!', '2007-09-19 10:29:16.000000', NULL, 1),
(4101422, 587934, 43463, '<td valign="top">Wow, this REALLY emulates the original. Catching a good steam pattern must be a bear, but you did nicely on this one. Colors and lighting are wonderful. The orange hues of the butterfly really pops off the predominately black background.</td>', 'Wow, this REALLY emulates the original. Catching a good steam pattern must be a bear, but you did nicely on this one. Colors and lighting are wonderful. The orange hues of the butterfly really pops off the predominately black background.', '2007-09-19 10:33:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4101428, 587960, 43463, '<td valign="top">Wow, lovely details on this roses from the gentle swoops of the petals to the water drops adorning them. The B&amp;W tones are stunning - you have a nice dynamic range. The roses really pop off that deep black background. Good job on this one.</td>', 'Wow, lovely details on this roses from the gentle swoops of the petals to the water drops adorning them. The B&W tones are stunning - you have a nice dynamic range. The roses really pop off that deep black background. Good job on this one.', '2007-09-19 10:36:27.000000', NULL, 1),
(4101444, 586235, 43463, '<td valign="top">The level of details in your capture is absolutely stunning! We see the details of this primate with absolute clarity from the texture in the hair to the smallest whiskers on it''s snout! Colors are also wonderful! You really bring the viewer in up close and personal with this monkey!</td>', 'The level of details in your capture is absolutely stunning! We see the details of this primate with absolute clarity from the texture in the hair to the smallest whiskers on it''s snout! Colors are also wonderful! You really bring the viewer in up close and personal with this monkey!', '2007-09-19 10:41:35.000000', NULL, 1),
(4101456, 587251, 43463, '<td valign="top">I absolutely love the colors captured here. The hues on that poppy really do pop off the page. You did a great job emulating Ursula''s piece. The hues of orange and yellow are bold &amp; vibrant yet I can almost ''feel" the petal softness as I gaze upon this composition. The bit of blue and green the peek through is the perfect complimentry background for this flower.</td>', 'I absolutely love the colors captured here. The hues on that poppy really do pop off the page. You did a great job emulating Ursula''s piece. The hues of orange and yellow are bold & vibrant yet I can almost ''feel" the petal softness as I gaze upon this composition. The bit of blue and green the peek through is the perfect complimentry background for this flower.', '2007-09-19 10:47:09.000000', NULL, 1),
(4101463, 585239, 43463, '<td valign="top">I think you nailed emulating the original with your composition. The B&amp;W tones are very dynamic and leap off the page. The shoe &amp; hands really emerge from the darkness of your black background to show us this ''silent'' scream. Great job!</td>', 'I think you nailed emulating the original with your composition. The B&W tones are very dynamic and leap off the page. The shoe & hands really emerge from the darkness of your black background to show us this ''silent'' scream. Great job!', '2007-09-19 10:51:02.000000', NULL, 1),
(4101474, 586120, 83350, '<td valign="top">Detail, from feather to beak, is fantastic!!</td>', 'Detail, from feather to beak, is fantastic!!', '2007-09-19 10:57:05.000000', NULL, 1),
(4101495, 588036, 83350, '<td valign="top">Great work!!</td>', 'Great work!!', '2007-09-19 11:03:50.000000', NULL, 1),
(4101497, 586892, 43463, '<td valign="top">Lighting and details on this photo composition are great! This is a very colorful photo - very literally:-) The lean of the impostor crayon subtly calls the viewers attention to the difference - especially when our eye travels past the crayola wrapping to notice a pencil tip. You did a good job on emulating the original.</td>', 'Lighting and details on this photo composition are great! This is a very colorful photo - very literally:-) The lean of the impostor crayon subtly calls the viewers attention to the difference - especially when our eye travels past the crayola wrapping to notice a pencil tip. You did a good job on emulating the original.', '2007-09-19 11:04:15.000000', NULL, 1),
(4101498, 587283, 83350, '<td valign="top">Great idea it comes together VERY well!</td>', 'Great idea it comes together VERY well!', '2007-09-19 11:04:51.000000', NULL, 1),
(4101503, 587664, 83350, '<td valign="top">Colors,lines and execution are GREAT!!</td>', 'Colors,lines and execution are GREAT!!', '2007-09-19 11:06:48.000000', NULL, 1),
(4101504, 587832, 43463, '<td valign="top">Wow! The whites of her eyes really stare back out at you! That is the first thing that reaches out, grabs you by the collar, and draws you in. You have a great dynamic range in your B&amp;W tones. The clarity of details in wonderful especially in your model''s face. Wonderful job you did here.</td>', 'Wow! The whites of her eyes really stare back out at you! That is the first thing that reaches out, grabs you by the collar, and draws you in. You have a great dynamic range in your B&W tones. The clarity of details in wonderful especially in your model''s face. Wonderful job you did here.', '2007-09-19 11:06:54.000000', NULL, 1),
(4101523, 588040, 43463, '<td valign="top">Wow, love how the frog really pops off that green backdrop. Level of details are wonderful. Lighting is good, but I think a little more illumination would bring out more details in the crevasses (the spaces between the bumps) of your  rasberry (hmmm, little confused on the color for a rasberry is red but a blackberry has more of those deep purple/black hues seen here). Good job on emulating the original.</td>', 'Wow, love how the frog really pops off that green backdrop. Level of details are wonderful. Lighting is good, but I think a little more illumination would bring out more details in the crevasses (the spaces between the bumps) of your  rasberry (hmmm, little confused on the color for a rasberry is red but a blackberry has more of those deep purple/black hues seen here). Good job on emulating the original.', '2007-09-19 11:12:50.000000', NULL, 1),
(4101535, 588035, 68546, '<td valign="top">very nice, a good subtle difference on the original but enough to keep it a copy. Very well executed</td>', 'very nice, a good subtle difference on the original but enough to keep it a copy. Very well executed', '2007-09-19 11:17:26.000000', NULL, 1),
(4101536, 586833, 43463, '<td valign="top">Love the sharp details one can see here from the cat''s whiskers to fine textures of the hairs of this feline. Colors are outstanding in this composition too. The amber golden glow of the cat''s eyes are very hypnotic. Good job on emulating the original.</td>', 'Love the sharp details one can see here from the cat''s whiskers to fine textures of the hairs of this feline. Colors are outstanding in this composition too. The amber golden glow of the cat''s eyes are very hypnotic. Good job on emulating the original.', '2007-09-19 11:17:33.000000', NULL, 1),
(4101543, 587809, 68546, '<td valign="top">Even better then the last one of these I just saw and that was excellent. 9</td>', 'Even better then the last one of these I just saw and that was excellent. 9', '2007-09-19 11:19:04.000000', NULL, 1),
(4101545, 587283, 68546, '<td valign="top">nice copy, good lighting</td>', 'nice copy, good lighting', '2007-09-19 11:19:38.000000', NULL, 1),
(4101552, 587563, 43463, '<td valign="top">Great job in emulating Scalvert''s photo! Love the addition of the colorful ''rug'' (hey, I think I have the same table runner!) for it adds a punch of color  to this composition. Details and lighting are wonderful. The boy''s pose and expression as he calls forth the deadly ''beltsnake'' is perfect:-)</td>', 'Great job in emulating Scalvert''s photo! Love the addition of the colorful ''rug'' (hey, I think I have the same table runner!) for it adds a punch of color  to this composition. Details and lighting are wonderful. The boy''s pose and expression as he calls forth the deadly ''beltsnake'' is perfect:-)', '2007-09-19 11:22:05.000000', NULL, 1),
(4101554, 587819, 68546, '<td valign="top">I think the lighting here really detracts from the shot. It''s caused very harsh and distracting shadows on the bridge supports. As well I don''t like the toning used on this shot. That said the technicals of the shot itsef are good, nice and sharp front to back and the composition is good</td>', 'I think the lighting here really detracts from the shot. It''s caused very harsh and distracting shadows on the bridge supports. As well I don''t like the toning used on this shot. That said the technicals of the shot itsef are good, nice and sharp front to back and the composition is good', '2007-09-19 11:22:12.000000', NULL, 1),
(4101564, 584989, 68546, '<td valign="top">Unfortunatley the eyes here seem very soft, the lips seem much sharper and draw my eye to them. A closer shot of the eyes would have been better here as well as the original very much filled the frame</td>', 'Unfortunatley the eyes here seem very soft, the lips seem much sharper and draw my eye to them. A closer shot of the eyes would have been better here as well as the original very much filled the frame', '2007-09-19 11:25:34.000000', NULL, 1),
(4101574, 587889, 68546, '<td valign="top">I really like this shot as a portrait of a sunflower. Unfortunately it''s not a good representation of Nuzzer''s shot in my opinion. His shot seemed to capture a lot more depth and feeling into it. This comes across as just a very good photo of a sunflower. I hope that makes sense?</td>', 'I really like this shot as a portrait of a sunflower. Unfortunately it''s not a good representation of Nuzzer''s shot in my opinion. His shot seemed to capture a lot more depth and feeling into it. This comes across as just a very good photo of a sunflower. I hope that makes sense?', '2007-09-19 11:27:53.000000', NULL, 1),
(4101583, 587254, 68546, '<td valign="top">fantastic! Amazing portrait technically in terms of focus, DoF, and composition. I think the expresion in Larus original is better but this is a great copy</td>', 'fantastic! Amazing portrait technically in terms of focus, DoF, and composition. I think the expresion in Larus original is better but this is a great copy', '2007-09-19 11:30:50.000000', NULL, 1),
(4101590, 587822, 68546, '<td valign="top">Whilst technically this is very good, very sharp, no lighting glare, composition is spot on. I think the colours and don''t work so well, comes across a little dull</td>', 'Whilst technically this is very good, very sharp, no lighting glare, composition is spot on. I think the colours and don''t work so well, comes across a little dull', '2007-09-19 11:32:59.000000', NULL, 1),
(4101596, 586466, 68546, '<td valign="top">Not quite as clean and polished as the original but a good copy, well done!</td>', 'Not quite as clean and polished as the original but a good copy, well done!', '2007-09-19 11:34:05.000000', NULL, 1),
