(4102534, 587283, 58452, '<td valign="top">Best effort in duplicating the moving water distortion on the music scale.  I also love the spot lighting.  Excellent.</td>', 'Best effort in duplicating the moving water distortion on the music scale.  I also love the spot lighting.  Excellent.', '2007-09-19 17:10:14.000000', NULL, 1),
(4102535, 586449, 19944, '<td valign="top">I think your white balance and the noise really hurt you here, as well as the lack of sharpness.  your tear also isn''t really well defined.</td>', 'I think your white balance and the noise really hurt you here, as well as the lack of sharpness.  your tear also isn''t really well defined.', '2007-09-19 17:10:40.000000', NULL, 1),
(4102539, 587805, 19944, '<td valign="top">Your subject is sharper than the original, but the lighthing just isn''t up to snuff.  That bright light in the back is actually distracting, as I am drawn to that, rather than the rope.</td>', 'Your subject is sharper than the original, but the lighthing just isn''t up to snuff.  That bright light in the back is actually distracting, as I am drawn to that, rather than the rope.', '2007-09-19 17:12:47.000000', NULL, 1),
(4102542, 588000, 58452, '<td valign="top">Love the precisely centered catchlights and mesmerizing expression.  Bumping up a point as I comment.  Excellent effort.</td>', 'Love the precisely centered catchlights and mesmerizing expression.  Bumping up a point as I comment.  Excellent effort.', '2007-09-19 17:13:14.000000', NULL, 1),
(4102546, 586120, 19944, '<td valign="top">Tough call...I''d say I give you a slight edge. The original scored a 7.4894.  I''d give this a 7.4895.  Soooooooo close.</td>', 'Tough call...I''d say I give you a slight edge. The original scored a 7.4894.  I''d give this a 7.4895.  Soooooooo close.', '2007-09-19 17:14:42.000000', NULL, 1),
(4102553, 587917, 19944, '<td valign="top">Quite humorous.  I''ll give you an extra point for creativity.</td>', 'Quite humorous.  I''ll give you an extra point for creativity.', '2007-09-19 17:15:24.000000', NULL, 1),
(4102554, 588039, 58452, '<td valign="top">Of the three checkerboard drops I like this one best.  The distortion of the background is more profound.  I think perhaps a bit more exposure might have resulted in slightly whiter squares, but that''s just a nit pic.  Very nice image.</td>', 'Of the three checkerboard drops I like this one best.  The distortion of the background is more profound.  I think perhaps a bit more exposure might have resulted in slightly whiter squares, but that''s just a nit pic.  Very nice image.', '2007-09-19 17:15:41.000000', NULL, 1),
