(4102573, 587665, 19944, '<td valign="top">Another tough call on which I prefer.  I''m leaning toward yours becasue I prefer the hands that you have used.  His may be a smidge better lighting.</td>', 'Another tough call on which I prefer.  I''m leaning toward yours becasue I prefer the hands that you have used.  His may be a smidge better lighting.', '2007-09-19 17:20:45.000000', NULL, 1),
(4102580, 587294, 19944, '<td valign="top">I like yours better than the original by just a bit.  Your background is nice and white.  Pidge''s has a slight pinkish cast on my monitor.  Otherwise, they are way to close to differentiate.</td>', 'I like yours better than the original by just a bit.  Your background is nice and white.  Pidge''s has a slight pinkish cast on my monitor.  Otherwise, they are way to close to differentiate.', '2007-09-19 17:22:42.000000', NULL, 1),
(4102590, 584989, 58452, '<td valign="top">Very librodo like effort.  I like the contrast of the pink of the hood with her skin tones. Your capture of her eyes is beautiful, although I''d like better defined catch lights.  That''s just a nit pick though.  Very nice.</td>', 'Very librodo like effort.  I like the contrast of the pink of the hood with her skin tones. Your capture of her eyes is beautiful, although I''d like better defined catch lights.  That''s just a nit pick though.  Very nice.', '2007-09-19 17:25:56.000000', NULL, 1),
